<?php
namespace Tests\Feature;
use App\Models\{AdmissionPeriod,Applicant,Payment};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class TripayWebhookTest extends TestCase {use RefreshDatabase;public function test_signed_paid_callback_updates_payment():void{$period=AdmissionPeriod::create(['name'=>'Aktif','year'=>2026,'registration_prefix'=>'PKU','starts_at'=>now(),'ends_at'=>now()->addDay(),'registration_fee'=>250000,'is_active'=>true]);$applicant=Applicant::create(['admission_period_id'=>$period->id,'registration_number'=>'PKU-2026-000888','submission_uuid'=>fake()->uuid(),'full_name'=>'Tripay Test','birth_place'=>'Jakarta','birth_date'=>'2000-01-01','address'=>'Alamat','whatsapp_normalized'=>'6281234567890','whatsapp_display'=>'0812','email'=>'tripay@example.test','payment_status'=>'unpaid','document_status'=>'pending_review','selection_status'=>'not_scheduled','consented_at'=>now(),'submitted_at'=>now()]);$payment=Payment::create(['applicant_id'=>$applicant->id,'provider'=>'tripay','merchant_ref'=>'INV-TRIPAY','provider_reference'=>'TREF-1','base_amount'=>250000,'total_amount'=>254000,'status'=>'unpaid']);config(['services.tripay.private_key'=>'private-secret']);$json=json_encode(['reference'=>'TREF-1','merchant_ref'=>'INV-TRIPAY','payment_method'=>'BRI VA','payment_method_code'=>'BRIVA','total_amount'=>254000,'fee_merchant'=>0,'fee_customer'=>4000,'status'=>'PAID']);$signature=hash_hmac('sha256',$json,'private-secret');$this->call('POST','/webhooks/tripay',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_X_CALLBACK_EVENT'=>'payment_status','HTTP_X_CALLBACK_SIGNATURE'=>$signature],$json)->assertOk();$this->assertSame('paid',$payment->fresh()->status);$this->assertSame('paid',$applicant->fresh()->payment_status->value);}}
